input.command:
cd /workspaces/.ai-chat-history/ai-chat-documentation/raw && grep -rlE 'Plugin already registered under a different name' . | head -4; f=$(grep -rlE 'Plugin already registered under a different name' . | grep -v 7057d269 | head -1); echo "file: $f"; [ -n "$f" ] && python3 -I - "$f" <<'EOF'
import sys,json,re
for line in open(sys.argv[1]):
    if 'Plugin already registered' in line:
        try: d=json.loads(line)
        except: continue
        s=json.dumps(d)
        i=s.find('Plugin already registered')
        print(re.sub(r'\\n','\n',s[max(0,i-600):i+300])[:1200]); print('=====')
EOF

